# rows
n = 0
for fname, tag, venues, label in SEASONS:
    rows = json.load(open(f'{LEDGER}/{fname}'))
    assert len(rows) == 380, f'{tag}: {len(rows)}'
    for r in rows:
        stadium = venues[r['home']] if venues else r['venue']
        city = CITY[r['home']]
        out.append(f'MATCH|{r["date"]}|Spain La Liga|domestic-league|{r["home"]}|{r["hg"]}|{r["ag"]}|{r["away"]}|MD{r["round"]}|{stadium}|{city}|Spain||{label}')
        n += 1
out.append('END')
assert n == 1900, n

text = '\n'.join(out) + '\n'
open(OUT, 'w', encoding='utf-8').write(text)
print(f'wrote {OUT}: {n} MATCH rows, {len(out)} lines')
